import argparse, datetime, json, sys, traceback
from pathlib import Path
sys.path.insert(0,'/home/zhongming/CodeNib-codegraph-benefit')
from scripts.contextbench_verified import grade_verified
ROOT=Path('/tmp/codenib-matched-pilot-20261027')
rows={r['instance_id']:r for r in json.loads((ROOT/'controller-native-cases.json').read_text())}
selected=json.loads((ROOT/'cohort-selection.json').read_text())['selection']['selected']
# Nonempty carrier required by native patch application. This is an empty
# production change, not a patch/test methodology change.
empty='diff --git a/.codenib_empty_control.txt b/.codenib_empty_control.txt\nnew file mode 100644\nindex 0000000..b32edc1\n--- /dev/null\n+++ b/.codenib_empty_control.txt\n@@ -0,0 +1 @@\n+No production changes.\n'
(ROOT/'empty-control.patch').write_text(empty)
records=[]
for selected_row in selected:
    row=rows[selected_row['instance_id']]
    selected_row={**selected_row,'local_native_image_id':next(x['image_id'] for x in json.loads((ROOT/'arm64-control-sources-v1-summary.json').read_text()) if x['instance_id']==selected_row['instance_id'])}
    for kind in ('empty-production','reference'):
        case=ROOT/'native-controls-arm64-v1'/row['instance_id']/kind
        case.mkdir(parents=True,exist_ok=False)
        patch=empty if kind=='empty-production' else row['patch']
        config={'repo':row['repo'],'source':'Verified','source_commit':row['base_commit'],'implementation':{},'image_id':selected_row['local_native_image_id']}
        solver={'instance_id':row['instance_id'],'original_inst_id':row['instance_id'],'model_patch':patch}
        pred=[{'instance_id':row['instance_id'],'model_patch':patch,'model_name_or_path':'pilot-control-'+kind}]
        for name,data in (('config.json',config),('solver.json',solver),('predictions.json',pred)):
            (case/name).write_text(json.dumps(data,indent=2))
        record={'instance_id':row['instance_id'],'kind':kind,'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
        print('START',record['instance_id'],kind,flush=True)
        try:
            grade_verified(argparse.Namespace(solver_run=case,dataset=ROOT/'controller-native-cases.json',output=case/'grade',timeout=300))
            record['outcome']=json.loads((case/'grade'/'resolution.json').read_text())
        except Exception as exc:
            record['error']={'type':type(exc).__name__,'message':str(exc),'traceback':traceback.format_exc()}
        records.append(record)
        (ROOT/'native-controls-arm64-v1-summary.json').write_text(json.dumps(records,indent=2))
        # Native files retain all output; console emits metadata only.
        print('END',record['instance_id'],kind,'result',record.get('outcome',{}).get('resolved'),'error',record.get('error',{}).get('type'),flush=True)

